        await repo.SaveAsync(order, ct);
}

using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

[MemoryDiagnoser]
public class CsvParseBench
{
    private readonly string _line = "sku,widget,42.50,US";

    [Benchmark(Baseline = true)]
    public decimal SplitParse() =>
        decimal.Parse(_line.Split(',')[2]);

    [Benchmark]
    public decimal SpanParse()
    {
        var span = _line.AsSpan();
        var third = span.Split(',')[2].Trim();
        return decimal.Parse(third);
    }
}
